export class EventBus{constructor(){this._listeners=new Map}on(evento,handler){if(typeof handler!=="function"){throw new TypeError("EventBus.on: handler debe ser una función")}if(!this._listeners.has(evento)){this._listeners.set(evento,new Set)}this._listeners.get(evento).add(handler);return()=>this.off(evento,handler)}once(evento,handler){const wrapper=(...args)=>{this.off(evento,wrapper);handler(...args)};return this.on(evento,wrapper)}off(evento,handler){const set=this._listeners.get(evento);if(!set)return;set.delete(handler);if(set.size===0)this._listeners.delete(evento)}emit(evento,...args){const set=this._listeners.get(evento);if(!set)return;Array.from(set).forEach(handler=>{try{handler(...args)}catch(err){console.error(`[EventBus] handler para "${evento}" tiró un error:`,err)}})}clear(evento){if(evento===undefined){this._listeners.clear()}else{this._listeners.delete(evento)}}}export const appEventBus=new EventBus;export default EventBus;